 * @method
 * @name init_datefmt_cal_redmptDd
 * @description 초기화 — datefmt cal redmpt Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_redmptDd = function () { $c.date.checkCalendarFormat("cal_redmptDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        /*달력셋팅*/

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05101.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldbnf05101: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.v_str = '' + dma_result.get("curr_tp_cd") + '';
        scwin.v_str1 = '' + dma_result.get("regInstCd") + '';
        scwin.v_str2 = '' + dma_result.get("regInstNm") + '';
        scwin.setAttachChk = setAttachChk;
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_datefmt_cal_isuDd();
        scwin.init_datefmt_cal_procsReqDd();
        scwin.init_datefmt_cal_redmptDd();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf05101.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05101.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05101.btn_mpd_files_del_onclick' }); }
};

