 */
scwin.ipt_isuAmt_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (($c.util.getComponent('txt_isuAmtHanview') && $c.util.getComponent('txt_isuAmtHanview').setValue) ? $c.util.getComponent('txt_isuAmtHanview').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) === null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, ''))) : console.warn('[sdd] num2won 대상 미해결: ' + 'isu_amt_hanview'));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05101.ipt_isuAmt_onkeyup' }); }
};

