scwin.addRow = function () {
    const fm = (document.SendForm || { elements: [] });
    const bf_file_cnt = parseInt($c.util.getComponent("ipt_fileSaveCnt").getValue());
    const af_file_cnt = parseInt($c.util.getComponent("ipt_fileRowNum").getValue()) - bf_file_cnt;
    const rowPlus = $c.util.getComponent("tbl_file");
    let tr;
    let th;
    let td;
    const newRowNum = rownum + 1;
    if (rownum === 0) {
        rowPlus.deleteRow(0);
    }
    const $tblFile = $('#tbl_file');
    const $tr = $("<tr></tr>").addClass('first');
    const $td1 = $("<td><input type=\"checkbox\" name=\"chk\" /></td>").addClass('first txc');
    const $td2 = $("<td><input type=\"text\" id=\"attach_file_nm\" name=\"attach_file_nm[" + af_file_cnt + "]\" readonly style=\"width: 200px; height:20px; vertical-align: 6px;\" class=\"file_input_textbox\" /><div class=\"file_input_div\"><img src=\"/images/btn_find.gif\" name=\"file_1\" class=\"file_input_img_btn\" alt=\"open\" /><input type=\"file\" name=\"attachFiles[" + af_file_cnt + "]\" style=\"width:91px; height:20px; \" onchange=\"fn_getFileNm(" + af_file_cnt + ");\" class=\"file_input_hidden\" /></div></td>");
    const $td3 = $("<td><input type=\"text\" name=\"file_coment\" style=\"width: 310px; height:20px;\" onpaste=\"return false;\" /></td>");
    const $td4 = $("<td><input type=\"hidden\" name=\"attach_file_tp_cd\" value=\"\"/>" + "<label><input type=\"radio\" name=\"attach_chk" + af_file_cnt + "\" value=\"1\" onclick=\"setAttachChk(" + af_file_cnt + ", this.value)\" /> 신고서/계약서</label>&nbsp;" + "<label><input type=\"radio\" name=\"attach_chk" + af_file_cnt + "\" value=\"2\" onclick=\"setAttachChk(" + af_file_cnt + ", this.value)\" /> 납입증명서</label>&nbsp;<br/>" + "<label><input type=\"radio\" name=\"attach_chk" + af_file_cnt + "\" value=\"4\" onclick=\"setAttachChk(" + af_file_cnt + ", this.value)\" /> 발행등록사실확인서</label>&nbsp;" + "<label><input type=\"radio\" name=\"attach_chk" + af_file_cnt + "\" value=\"3\" onclick=\"setAttachChk(" + af_file_cnt + ", this.value)\" /> 기타</label>&nbsp;</td>");
    $tr.append($td1);
    $tr.append($td2);
    $tr.append($td3);
    $tr.append($td4);
    $tblFile.append($tr);
    rownum++;
    reNames();
};

